def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    top=[(j,v) for j,v in enumerate(grid[0]) if v]
    endpoints={}
    for i in range(1,h):
        for j in (0,w-1):
            v=grid[i][j]
            if v: endpoints[v]=(i,j)
    for j,v in top:
        end=endpoints.get(v)
        if end:
            i,edge=end
            # vertical segment joins top mark to endpoint, except a left-edge endpoint's rail continues to bottom
            last=h-1 if edge==0 else i
        else:
            last=h-1
        for r in range(last+1):g[r][j]=v
    for v,(i,edge) in endpoints.items():
        j=next((j for j,c in top if c==v),None)
        if j is None:continue
        if edge==0:
            for c in range(j+1):g[i][c]=v
        else:
            for c in range(j,w):g[i][c]=v
    return g
